mapper.select:
with deal as (select TOTLE_TRADE_ID, BUSI_TYPE, FINPROD_ID, FINPROD_TYPE2, TRADE_DATE, TRADE_STATUS, PS, TRADE_AMT, INT_AMT, SHARE_AMT, FPRICE_AMT, PRIN_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE trade_status = '01' AND is_cancel = 'N'), deal1 as (select FINPROD_ID, PS, FINPROD_TYPE2, nvl(sum(TRADE_AMT), 0) TRADE_AMT, nvl(sum(SHARE_AMT), 0) SHARE_AMT, nvl(sum(INT_AMT), 0) INT_AMT, nvl(sum(PRIN_AMT), 0) PRIN_AMT, nvl(sum(FPRICE_AMT), 0) FPRICE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL where (TRADE_DATE is null or TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd')) and trade_status = '01' AND is_cancel = 'N' group by FINPROD_ID, PS, FINPROD_TYPE2) select * from (select distinct(select FIN_CASH_PAY_RULE.PAY_TYPE from FIN_CASH_PAY_RULE where FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id AND FIN_CASH_INFO.CASH_TYPE_1 = '02' AND FIN_CASH_INFO.CASH_TYPE_2 = 'C02' and FIN_CASH_PAY_RULE.eff_date = (SELECT MAX(FIN_CASH_PAY_RULE.eff_date) AS max_eff_date FROM FIN_CASH_PAY_RULE WHERE FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id and PRD_SALE_PARAM.FIRST_SALE_VDATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd'))) bonusMode, (select FIN_CASH_PAY_RULE.PAY_CYCLE from FIN_CASH_PAY_RULE where FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id AND FIN_CASH_INFO.CASH_TYPE_1 = '02' AND FIN_CASH_INFO.CASH_TYPE_2 = 'C02' and FIN_CASH_PAY_RULE.eff_date = (SELECT MAX(FIN_CASH_PAY_RULE.eff_date) AS max_eff_date FROM FIN_CASH_PAY_RULE WHERE FIN_CASH_INFO.cash_id = FIN_CASH_PAY_RULE.cash_id and PRD_SALE_PARAM.FIRST_SALE_VDATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd'))) intpayPeriod,
(case when FIN_PRODUCT_ADD.DEAL_MODE = '11' then (select round(case when SUM(TDY_POSITION) = 0 then 0 else nvl2(sum(TDY_POSITION), sum(nvl(TDY_POSITION, 0) * nvl(TDY_FEE_RATE, 0)) / sum(TDY_POSITION), 0) end, 4) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.finprod_id and bop.FEE_TYPE = 'C03' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C03' and BOK_POSITION_PRDFEE.CDATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd'))) else (select nvl(TDY_FEE_RATE, 0) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.FINPROD_ID and bop.FEE_TYPE = 'C03' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C03' and BOK_POSITION_PRDFEE.CDATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd'))) end) * 100 fixFeeProportion, (case when FIN_PRODUCT_ADD.DEAL_MODE = '11' then (select round(decode(SUM(TDY_POSITION), null, 0, 0, 0, SUM(nvl(TDY_POSITION, 0) * nvl(TDY_FEE_RATE, 0)) / SUM(TDY_POSITION)), 4) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.finprod_id and bop.FEE_TYPE = 'C05' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C05' and BOK_POSITION_PRDFEE.CDATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd'))) else (select nvl(TDY_FEE_RATE, 0) from BOK_POSITION_PRDFEE bop where bop.FINPROD_ID = fin_product.FINPROD_ID and bop.FEE_TYPE = 'C05' and bop.CDATE = (select MAX(BOK_POSITION_PRDFEE.CDATE) MAX_CDATE from BOK_POSITION_PRDFEE where BOK_POSITION_PRDFEE.FINPROD_ID = fin_product.finprod_id and BOK_POSITION_PRDFEE.FEE_TYPE = 'C05' and BOK_POSITION_PRDFEE.CDATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd'))) end) * 100 trustFeeProportion, (select CUS_YEAR_YIELD from CHB_PRD_END_SUB where CHB_PRD_END_SUB.PROD_ID = FIN_PRODUCT.FINPROD_MARKET_ID and CHB_PRD_END_SUB.SEND_STATUS != '01') actYield, (select nvl(sum(TRADE_AMT), 0) from deal where deal.ps = 'C1' and deal.finprod_id = fin_product.finprod_id and deal.trade_status != '03' group by deal.finprod_id) firstPrinAmt, ((select nvl(sum(SHARE_AMT), 0) from deal where deal.ps in ('C1', 'C2', 'C3', 'C10') and deal.trade_status != '03' and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd')) - (select nvl(sum(SHARE_AMT), 0) from deal where deal.ps in ('C6', 'C4', 'C5', 'C17', 'C19', 'C20') and deal.trade_status != '03' and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd'))) shareAmt, (case when fin_product.PROFIT_TYPE = '02' then (select nvl(sum(INT_AMT), 0) from deal where deal.ps in ('C4', 'C5', 'C17', 'C20') and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd') group by deal.finprod_id) when fin_product.PROFIT_TYPE in ('01', '03') then (select nvl(sum(FPRICE_AMT), 0) from deal where deal.ps in ('C9', 'C10') and deal.finprod_id = fin_product.finprod_id and deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd') group by deal.finprod_id) else 0 end) custProfit, (select TRADE_AMT from deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C05' and deal1.finprod_id = fin_product.finprod_id) trustFee, (select TRADE_AMT from deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C06' and deal1.finprod_id = fin_product.finprod_id) saleFee, (select TRADE_AMT from deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C03' and deal1.finprod_id = fin_product.finprod_id) fixFee, (select TRADE_AMT from deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C10' and deal1.finprod_id = fin_product.finprod_id) proxyFee, (select TRADE_AMT from deal1 where deal1.ps = 'C12' and deal1.finprod_type2 is null and deal1.finprod_id = fin_product.finprod_id) addTax, (case when fin_product.PROFIT_TYPE in ('01', '03') then (select TRADE_AMT from deal1 where deal1.ps = 'C11' and deal1.finprod_type2 = 'C04' and deal1.finprod_id = fin_product.finprod_id) end) floatFee, (select sum(TRADE_AMT) from deal1 where deal1.ps = 'C11' and deal1.finprod_type2 is not null and deal1.finprod_type2 not in ('C03', 'C04', 'C05', '04', 'C06', 'C10') and deal1.finprod_id = fin_product.finprod_id group by deal1.finprod_id) otherFee, (select sum(TRADE_AMT) from deal1 where deal1.ps = 'C11' and deal1.finprod_type2 in ('12', '04') and deal1.finprod_id = fin_product.finprod_id) actMidIncome, (select nvl(sum(TRADE_AMT), 0) from deal where deal.ps in ('C1', 'C2') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd') and deal.TRADE_DATE >= to_date(#{queryDateStart,jdbcType=DATE}, 'yyyy-MM-dd'))) group by deal.finprod_id) monthIssuePrinamt, (select nvl(sum(SHARE_AMT), 0) from deal where deal.ps in ('C1', 'C2') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd') and deal.TRADE_DATE >= to_date(#{queryDateStart,jdbcType=DATE}, 'yyyy-MM-dd'))) group by deal.finprod_id) monthIssueShareamt, (select nvl(sum(TRADE_AMT), 0) from deal where deal.ps in ('C4', 'C5', 'C17', 'C6', 'C20') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd') and deal.TRADE_DATE >= to_date(#{queryDateStart,jdbcType=DATE}, 'yyyy-MM-dd'))) group by deal.finprod_id) monthDuePrinamt, (select nvl(sum(SHARE_AMT), 0) from deal where deal.ps in ('C4', 'C5', 'C17', 'C6', 'C20') and deal.finprod_id = fin_product.finprod_id and (deal.TRADE_DATE is null or (deal.TRADE_DATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd') and deal.TRADE_DATE >= to_date(#{queryDateStart,jdbcType=DATE}, 'yyyy-MM-dd'))) group by deal.finprod_id) monthDueShareamt, FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT_ADD.DEAL_MODE dealMode from FIN_PRODUCT left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PTL_PORTFOLIO_AUTHORITY on FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.FINPROD_TYPE = '01' and FIN_CASH_INFO.CASH_TYPE_1 = '02' and FIN_CASH_INFO.CASH_TYPE_2 = 'C02' and FIN_CASH_INFO.BRANCH = 0 left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID left join FIN_BASE_RULE_INFO ON FIN_PRODUCT.FINPROD_ID = FIN_BASE_RULE_INFO.FINPROD_ID AND FIN_BASE_RULE_INFO.BASE_RULE_TYPE = '01' and FIN_BASE_RULE_INFO.EFF_DATE = FIN_PRODUCT.VDATE LEFT JOIN (select NVL(PRO.P_FINPROD_ID, pro.finprod_id) finprod_id, listagg(t.YIELD * 100, '/') within group(order by t.eff_date) yield from fin_cash_calc_rule t LEFT JOIN FIN_CASH_INFO CASH ON T.CASH_ID = CASH.CASH_ID and cash.cash_type_1 = '02' and cash.cash_type_2 = 'C02' left join fin_product pro on cash.finprod_id = pro.finprod_id where pro.profit_type = '02' and (t.eff_date, t.cash_id) in (select max(eff_date), cash_id from FIN_CASH_CALC_RULE where eff_date <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-mm-dd') group by cash_id) group by NVL(PRO.P_FINPROD_ID, pro.finprod_id)) YJ on YJ.finprod_id = FIN_PRODUCT.FINPROD_ID LEFT JOIN (select NVL(PRO.P_FINPROD_ID, pro.finprod_id) finprod_id, listagg(t.rate * 100, '/') within group(order by t.eff_date) rate from FIN_BASE_RULE_INFO t left join fin_product pro on t.finprod_id = pro.finprod_id where pro.profit_type != '02' and t.BASE_RULE_TYPE = '02' and (t.eff_date, t.finprod_id) in (select max(eff_date), finprod_id from FIN_CASH_CALC_RULE where eff_date <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-mm-dd') group by finprod_id) group by NVL(PRO.P_FINPROD_ID, pro.finprod_id)) YJ2 on YJ2.finprod_id = FIN_PRODUCT.FINPROD_ID where FIN_PRODUCT.P_FINPROD_ID IS NULL and PRD_SALE_PARAM.FIRST_SALE_VDATE <= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd')
and (
)
) order by finprodId

mapper.sql:
FIN_PRODUCT.FINPROD_ID IN (SELECT T1.FINPROD_ID FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID WHERE T1.FINPROD_TYPE2 = 'F16' AND T1.LIQUIDATION_DATE >= to_date(#{batchDate,jdbcType=DATE}, 'yyyy-MM-dd')
AND (T1.FINPROD_ID IN (#{item}) OR T2.PORTFOLIO_ID IN (#{item}))
)

mapper.select:
select * from FIN_BASE_RULE_INFO
where FINPROD_ID = #{finProdId,jdbcType=VARCHAR}
AND BRANCH = #{finBrach,jdbcType=INTEGER}
AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}

	and EFF_DATE <= 
	to_date(#{queryDate}, 'yyyy-MM-dd')

ORDER BY EFF_DATE DESC

select LEV lev, BASE_RULE_ID baseRuleId, COEFFICIENT coefficient, SPREAD_RATE * 100 spreadRate, CHARGE_RATIO * 100 chargeRatio from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO, FIN_PRODUCT, FIN_PRODUCT_ADD where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = FIN_CASH_INFO.CASH_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} and FIN_CASH_INFO.BRANCH = 0 AND (FIN_CASH_INFO.FINPROD_ID = #{finprodId}) and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}
and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
and (FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})
order by LEV

SELECT FIN_FLOAT_CALC_RULE_DETAIL.LEV lev, FIN_FLOAT_CALC_RULE_DETAIL.SPREAD_RATE*100 spreadRate, FIN_FLOAT_CALC_RULE_DETAIL.BASE_RULE_ID baseRuleId, FIN_FLOAT_CALC_RULE_DETAIL.COEFFICIENT coefficient, FIN_FLOAT_CALC_RULE_DETAIL.CHARGE_RATIO*100 chargeRatio FROM FIN_FLOAT_CALC_RULE_DETAIL
FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
AND to_char(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'yyyy-MM-dd') = #{effDate}
ORDER BY FIN_FLOAT_CALC_RULE_DETAIL.LEV ASC

select LEV lev,
BASE_RULE_ID baseRuleId,
COEFFICIENT coefficient,
SPREAD_RATE * 100 spreadRate,
CHARGE_RATIO * 100 chargeRatio
from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO,
FIN_PRODUCT, FIN_PRODUCT_ADD
where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID =
FIN_CASH_INFO.CASH_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = 0
AND ((FIN_CASH_INFO.FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE != #{dealMode10})
OR (FIN_PRODUCT.P_FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode10}
AND FIN_PRODUCT_ADD.TERM_TYPE != #{termType02}))
and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

	and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}

and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = (
select MAX(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE)
from FIN_FLOAT_CALC_RULE_DETAIL, FIN_CASH_INFO, FIN_PRODUCT,
FIN_PRODUCT_ADD
where FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = FIN_CASH_INFO.CASH_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = 0
and FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE <= to_date(#{queryDate},
'yyyy-MM-dd')
AND ((FIN_CASH_INFO.FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE != #{dealMode10})
OR (FIN_PRODUCT.P_FINPROD_ID = #{finprodId} and
FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode10}
AND FIN_PRODUCT_ADD.TERM_TYPE != #{termType02}))
and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

	and FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}

)
order by LEV

select FIN_BASE_RULE_INFO.BASE_RULE_ID baseRuleId, FIN_BASE_RULE_INFO.EFF_DATE effDate, FIN_BASE_RULE_INFO.RATE_TYPE rateType, FIN_BASE_RULE_INFO.RATE*100 rate, FIN_BASE_RULE_INFO.COEFFICIENT coefficient, FIN_BASE_RULE_INFO.INDEX_ID indexId, FIN_BASE_RULE_INFO.INDEX_SOURCE indexSource, FIN_BASE_RULE_INFO.SPREAD_RATE*100 spreadRate, FIN_BASE_RULE_INFO.RESET_TYPE resetType, prd_layer_param.PROD_STYLE prodStyle, prd_layer_param.TERM_MAX investmentCycle, FIN_BASE_RULE_INFO.BASE_RULE_TYPE baseRuleType, FIN_BASE_RULE_INFO.PUBLISH_TYPE publishType, FIN_BASE_RULE_INFO.RATE_LOWER*100 rateLower, FIN_BASE_RULE_INFO.RATE_LIMIT*100 rateLimit, FIN_PRODUCT.VDATE vdate, FIN_BASE_RULE_INFO.FINPROD_ID finprodId from FIN_BASE_RULE_INFO, FIN_PRODUCT left join prd_layer_param on FIN_PRODUCT.FINPROD_ID = prd_layer_param.FINPROD_ID where FIN_BASE_RULE_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and (FIN_BASE_RULE_INFO.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} or prd_layer_param.P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR})
AND FIN_BASE_RULE_INFO.BASE_RULE_TYPE = #{baseRuleType,jdbcType=VARCHAR}
AND FIN_BASE_RULE_INFO.PUBLISH_TYPE = #{publishType,jdbcType=VARCHAR}
and FIN_BASE_RULE_INFO.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
and (FIN_BASE_RULE_INFO.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})

select FIN_BASE_RULE_INFO.BASE_RULE_ID baseRuleId, FIN_BASE_RULE_INFO.EFF_DATE effDate, FIN_BASE_RULE_INFO.RATE_TYPE rateType, FIN_BASE_RULE_INFO.RATE*100 rate, FIN_BASE_RULE_INFO.COEFFICIENT coefficient, FIN_BASE_RULE_INFO.INDEX_ID indexId, FIN_BASE_RULE_INFO.INDEX_SOURCE indexSource, FIN_BASE_RULE_INFO.SPREAD_RATE*100 spreadRate, FIN_BASE_RULE_INFO.RESET_TYPE resetType, FIN_BASE_RULE_INFO.BASE_RULE_TYPE baseRuleType, FIN_BASE_RULE_INFO.PUBLISH_TYPE publishType, FIN_BASE_RULE_INFO.RATE_LOWER*100 rateLower, FIN_BASE_RULE_INFO.RATE_LIMIT*100 rateLimit, FIN_BASE_RULE_INFO.FINPROD_ID finprodId from FIN_BASE_RULE_INFO where FINPROD_ID = #{finProdId,jdbcType=VARCHAR} AND BRANCH = #{finBrach,jdbcType=INTEGER} AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}
and EFF_DATE <= to_date(#{queryDate}, 'yyyy-MM-dd')
ORDER BY EFF_DATE DESC

select CUSTOM_LEVEL customLevel, AMT_MIN amtMin, AMT_MAX amtMax, TERM_MAX termMax, TERM_MIN termMin, YIELD * 100 yield, REMARK remark, P_FINPROD_ID pFinprodId, VDATE vdate, nvl(PROD_STYLE,TERM_MAX) prodStyle, SALE_CHANNEL saleChannel, SALE_DEPARTMENT saleDepartment, TAR_CUSTOMER_TYPE tarCustomerType, IS_SALE isSale ,FINPROD_ID finprodId from PRD_LAYER_PARAM where 1=1
AND P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and P_FINPROD_ID in (select FINPROD_ID FROM FIN_PRODUCT where FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR} AND p_finprod_id is null)

		select * from FIN_BASE_RULE_INFO
		where FINPROD_ID = #{finProdId,jdbcType=VARCHAR}
		AND BRANCH = #{finBrach,jdbcType=INTEGER}
		AND BASE_RULE_TYPE = #{finBaseRuleType,jdbcType=VARCHAR}
		AND eff_date = (                                                                       
            SELECT MAX(eff_date) FROM FIN_BASE_RULE_INFO  WHERE FINPROD_ID=#{finProdId} AND EFF_DATE<=#{queryDate}                                                             
                AND BRANCH = #{finBrach} AND BASE_RULE_TYPE = #{finBaseRuleType})

		select FIN_BASE_RULE_INFO.*,
           PRD_LAYER_PARAM.PROD_STYLE,
           PRD_LAYER_PARAM.TERM_MAX
	    from FIN_BASE_RULE_INFO inner join PRD_LAYER_PARAM
	         on FIN_BASE_RULE_INFO.FINPROD_ID = PRD_LAYER_PARAM.Finprod_Id
	     where (FIN_BASE_RULE_INFO.FINPROD_ID = #{finProdId,jdbcType = VARCHAR} 
	             OR PRD_LAYER_PARAM.P_FINPROD_ID = #{finProdId,jdbcType = VARCHAR} )
	       AND FIN_BASE_RULE_INFO.BRANCH =#{finBrach,jdbcType = INTEGER}
	       AND FIN_BASE_RULE_INFO.BASE_RULE_TYPE = #{finBaseRuleType,jdbcType = VARCHAR}
	       AND (FIN_BASE_RULE_INFO.Finprod_Id, FIN_BASE_RULE_INFO.eff_date) in
	           (SELECT fbri.FINPROD_ID, MAX(fbri.eff_date)
	              FROM FIN_BASE_RULE_INFO fbri
	              inner join PRD_LAYER_PARAM plp on fbri.FINPROD_ID = plp.Finprod_Id
	             WHERE (fbri.FINPROD_ID = #{finProdId,jdbcType = VARCHAR} 
	                    OR plp.P_FINPROD_ID = #{finProdId,jdbcType = VARCHAR} )
	               AND fbri.EFF_DATE <= #{queryDate}
	               AND fbri.BRANCH = #{finBrach,jdbcType = INTEGER}
	               AND fbri.BASE_RULE_TYPE = #{finBaseRuleType,jdbcType = VARCHAR}
	             GROUP BY fbri.FINPROD_ID)
